#!/usr/bin/env python3
# USV UG-DSL: Akkubetrieb bleibt gueltig, Pushover bei OL/OB, Anzeige UG-DSL.
# Basis: Stand nach PR 18 und PR 19. Kein pip, kein apt, kein echter Versand.
from __future__ import annotations
import base64, hashlib, json, os, shutil, sys
from datetime import datetime
from pathlib import Path

DASH = Path("/home/fmg/prepper-dashboard")
DATEIEN = ("dashboard.py", "ups_manager.py", "pushover_push.py", "lage_pages.py", "prepper_docs.py")
GENAU = {
    "ups_manager.py": ("6658f0ef31f060f4281a11679580e7d6b4b90709853eda4a844d4f84f65d42dd", 64197),
    "pushover_push.py": ("76cdcadc41376a94a05c86d443e21104d803c01b58ea68d33469ce5865feb717", 10600),
    "prepper_docs.py": ("eaaf54b50c03b92d3eb69191d8354a9dc1b1bb7598708e6bb07161d54f57e6d8", 202122),
}
LAGE = (("4b59126142f681cf", 216825), ("f593e87b9dd8c46a", 216599))
MARKER = "UG-DSL".encode()

def load():
    raw = PAYLOAD if isinstance(PAYLOAD, dict) else json.loads(PAYLOAD)
    return {name: [(base64.b64decode(x["old"]), base64.b64decode(x["new"])) for x in raw[name]] for name in DATEIEN}

def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()

def basis_ok(name, data: bytes) -> bool:
    if b"KG-DSL" in data:
        return False
    if name in GENAU:
        h, n = GENAU[name]
        return sha(data) == h and len(data) == n
    if name == "dashboard.py":
        return b"pushoverKachel" in data and b"_psh_usv_kante" not in data and MARKER not in data
    if name == "lage_pages.py":
        h = sha(data)
        return b"<span>USV EG</span>" in data and MARKER not in data and any(h.startswith(p) and len(data) == n for p, n in LAGE)
    return False

def fenster(now=None):
    from zoneinfo import ZoneInfo
    jetzt = now or datetime.now(ZoneInfo("Europe/Berlin"))
    m = jetzt.minute
    return (not (m >= 45 or m <= 4)), "Berlin Minute %02d" % m

def schreiben(path: Path, data: bytes):
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    tmp = path.with_name("." + path.name + ".tmp-ugdsl")
    if tmp.exists():
        raise RuntimeError("temporaere Datei existiert")
    try:
        with open(tmp, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(tmp, mode)
        os.replace(tmp, path)
    finally:
        if tmp.exists():
            try:
                tmp.unlink()
            except OSError:
                pass

def sichern(path: Path, data: bytes):
    stempel = datetime.now().astimezone().strftime("%Y%m%dT%H%M%S")
    alt = sorted(path.parent.glob(path.name + ".bak-ugdsl-*"))
    bak = path.with_name(path.name + ".bak-ugdsl-" + stempel)
    shutil.copy2(path, bak)
    if bak.read_bytes() != data:
        bak.unlink()
        raise RuntimeError("Sicherung weicht ab")
    for alt_pfad in alt[:-2]:
        try:
            alt_pfad.unlink()
        except OSError:
            pass

def verwandle(data, pairs):
    if MARKER in data and b"_eg_is_wait" in data or (MARKER in data and all(data.count(neu) == 1 for _, neu in pairs) and b"KG-DSL" not in data):
        if all(data.count(neu) == 1 for _, neu in pairs) and b"KG-DSL" not in data:
            return data
    neu_data = data
    for old, neu in pairs:
        if neu_data.count(neu) == 1 and neu_data.count(old) == 0:
            continue
        if neu_data.count(old) != 1 or neu_data.count(neu) != 0:
            raise RuntimeError("Stelle")
        vor = neu_data
        neu_data = neu_data.replace(old, neu, 1)
        if neu_data.replace(neu, b"", 1) != vor.replace(old, b"", 1):
            raise RuntimeError("ausserhalb")
    if MARKER not in neu_data or b"KG-DSL" in neu_data:
        raise RuntimeError("Marker")
    return neu_data

def apply_dir(ordner: Path, dry: bool, kein: bool) -> int:
    paare = load()
    for name in DATEIEN:
        pfad = ordner / name
        if pfad.is_symlink() or not pfad.is_file():
            print("STOP: %s fehlt" % name)
            return 2
    blobs = {name: (ordner / name).read_bytes() for name in DATEIEN}
    for name, data in blobs.items():
        print("%s sha16 %s" % (name, sha(data)[:16]))
    ziel = {}
    for name in DATEIEN:
        try:
            ziel[name] = verwandle(blobs[name], paare[name])
        except RuntimeError:
            print("STOP: %s Stelle unbekannt" % name)
            return 2
    if all(ziel[name] == blobs[name] for name in DATEIEN):
        print("bereits installiert, keine Aenderung, kein Neustart")
        return 0
    for name in DATEIEN:
        if ziel[name] == blobs[name]:
            continue
        if not basis_ok(name, blobs[name]):
            print("STOP: %s %s ist nicht die Basis" % (name, sha(blobs[name])[:16]))
            return 2
    for name in ("ups_manager.py", "pushover_push.py", "dashboard.py"):
        try:
            compile(ziel[name], name, "exec")
        except SyntaxError as exc:
            print("STOP: Syntax %s %s" % (name, exc.lineno))
            return 2
    if b"usv_eg.json" not in ziel["ups_manager.py"] or b'EG_UPS = "usv_eg"' not in ziel["ups_manager.py"]:
        print("STOP: interner Name usv_eg wuerde verschwinden")
        return 2
    frei, meldung = fenster()
    print(meldung)
    if not frei and not dry:
        print("STOP: Neustart-Sperre Minute 45-59 und 00-04 Berlin. Nichts geschrieben.")
        return 2
    if dry:
        print("DRY-RUN: kein Backup, kein Schreiben, kein Neustart")
        return 0
    try:
        for name in DATEIEN:
            if ziel[name] == blobs[name]:
                continue
            sichern(ordner / name, blobs[name])
            schreiben(ordner / name, ziel[name])
    except (OSError, RuntimeError) as exc:
        print("STOP beim Schreiben: %s" % exc)
        return 3
    print("geschrieben. Akkubetrieb UG-DSL gueltig, Pushover bei Wechsel. usv_eg bleibt.")
    if kein:
        print("Kein Neustart in dieser Pruefung.")
        return 0
    frei, meldung = fenster()
    print(meldung)
    if not frei:
        print("STOP: Datei ist neu, der Neustart bleibt in der Sperre aus.")
        return 2
    import subprocess
    subprocess.run(["systemctl", "restart", "prepper-dashboard.service"], check=False)
    print("Nur prepper-dashboard neu gestartet.")
    return 0

def selftest() -> int:
    assert fenster(datetime(2026, 11, 12, 12, 10))[0] and fenster(datetime(2026, 11, 12, 12, 5))[0]
    assert not fenster(datetime(2026, 11, 12, 12, 45))[0]
    assert not fenster(datetime(2026, 11, 12, 12, 0))[0] and not fenster(datetime(2026, 11, 12, 12, 4))[0]
    assert basis_ok("ups_manager.py", b"x") is False
    assert basis_ok("dashboard.py", b"KG-DSL pushoverKachel") is False
    import tempfile
    ordner = Path(tempfile.mkdtemp(prefix="ugdsl-apply-"))
    for name in DATEIEN:
        (ordner / name).write_bytes(b"UNBERUEHRT-" + name.encode())
    vorher = {name: (ordner / name).read_bytes() for name in DATEIEN}
    rc = apply_dir(ordner, False, True)
    assert rc == 2 and {name: (ordner / name).read_bytes() for name in DATEIEN} == vorher
    print("selftest ok")
    return 0

def main(argv):
    args = argv[1:]
    dry = kein = False
    wurzel = DASH
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--dry-run":
            dry = True
        elif a == "--kein-neustart":
            kein = True
        elif a == "--selftest":
            return selftest()
        elif a == "--wurzel":
            i += 1
            wurzel = Path(args[i])
        else:
            print("STOP: unbekanntes Argument")
            return 2
        i += 1
    return apply_dir(wurzel, dry, kein)

